-- 修正 eduai 采集示例流程
--
-- 背景（承接 V1.15__eduai_collect_flows.sql）：
--   1. 古诗示例原先只写了 1 个种子 URL（poet.tang.0.json），流程名叫「全唐诗」却只采
--      1/58 的数据；且抓取节点用 ${url[0]} 硬取第一条，加多少分片都只跑第一片。
--   2. 原源站 cdn.jsdelivr.net 的 A 记录里存在被拒连的节点，而 JDK HttpClient 不会像
--      curl 那样换 IP 重试，于是任务直接以 IO 异常: ConnectException 失败。
--
-- 这里做的修正（幂等，按 collect_flow_code 定位，重复执行结果一致）：
--   * 开始节点列出全部分片（0..57000，共 58 个）；
--   * 抓取节点改为 ${item} + loopCount=${url}，一片一轮迭代；
--   * 源换成 fastly.jsdelivr.net，并开 retry=3 / retryInterval=2000 / timeout=120000。
--
-- 不改 V1.15 本体：那个版本已经应用过，改它会破坏 Flyway 校验和。

UPDATE collect_flow
SET collect_flow_dsl = '{"name":"古诗采集·全唐诗","threadCount":4,"headers":[],"cookies":[],"variables":[],"nodes":[{"id":"start","shape":"start","name":"开始","x":40,"y":160,"params":[{"name":"urls","value":"https://fastly.jsdelivr.net/gh/chinese-poetry/chinese-poetry-zhCN@master/poetry/poet.tang.0.json\\nhttps://fastly.jsdelivr.net/gh/chinese-poetry/chinese-poetry-zhCN@master/poetry/poet.tang.1000.json\\nhttps://fastly.jsdelivr.net/gh/chinese-poetry/chinese-poetry-zhCN@master/poetry/poet.tang.2000.json\\nhttps://fastly.jsdelivr.net/gh/chinese-poetry/chinese-poetry-zhCN@master/poetry/poet.tang.3000.json\\nhttps://fastly.jsdelivr.net/gh/chinese-poetry/chinese-poetry-zhCN@master/poetry/poet.tang.4000.json\\nhttps://fastly.jsdelivr.net/gh/chinese-poetry/chinese-poetry-zhCN@master/poetry/poet.tang.5000.json\\nhttps://fastly.jsdelivr.net/gh/chinese-poetry/chinese-poetry-zhCN@master/poetry/poet.tang.6000.json\\nhttps://fastly.jsdelivr.net/gh/chinese-poetry/chinese-poetry-zhCN@master/poetry/poet.tang.7000.json\\nhttps://fastly.jsdelivr.net/gh/chinese-poetry/chinese-poetry-zhCN@master/poetry/poet.tang.8000.json\\nhttps://fastly.jsdelivr.net/gh/chinese-poetry/chinese-poetry-zhCN@master/poetry/poet.tang.9000.json\\nhttps://fastly.jsdelivr.net/gh/chinese-poetry/chinese-poetry-zhCN@master/poetry/poet.tang.10000.json\\nhttps://fastly.jsdelivr.net/gh/chinese-poetry/chinese-poetry-zhCN@master/poetry/poet.tang.11000.json\\nhttps://fastly.jsdelivr.net/gh/chinese-poetry/chinese-poetry-zhCN@master/poetry/poet.tang.12000.json\\nhttps://fastly.jsdelivr.net/gh/chinese-poetry/chinese-poetry-zhCN@master/poetry/poet.tang.13000.json\\nhttps://fastly.jsdelivr.net/gh/chinese-poetry/chinese-poetry-zhCN@master/poetry/poet.tang.14000.json\\nhttps://fastly.jsdelivr.net/gh/chinese-poetry/chinese-poetry-zhCN@master/poetry/poet.tang.15000.json\\nhttps://fastly.jsdelivr.net/gh/chinese-poetry/chinese-poetry-zhCN@master/poetry/poet.tang.16000.json\\nhttps://fastly.jsdelivr.net/gh/chinese-poetry/chinese-poetry-z