/chinese-poetry-zhCN@master/poetry/poet.tang.56000.json\\nhttps://fastly.jsdelivr.net/gh/chinese-poetry/chinese-poetry-zhCN@master/poetry/poet.tang.57000.json"}],"fields":[]},{"id":"req","shape":"request","name":"抓取全唐诗分片","x":260,"y":160,"params":[{"name":"url","value":"${item}"},{"name":"method","value":"GET"},{"name":"saveDocument","value":"0"},{"name":"timeout","value":"120000"},{"name":"loopCount","value":"${url}"},{"name":"loopVariableName","value":"shardIndex"},{"name":"loopItemVariableName","value":"item"},{"name":"retry","value":"3"},{"name":"retryInterval","value":"2000"}],"fields":[]},{"id":"ext","shape":"extract","name":"抽取诗词字段","x":480,"y":160,"params":[{"name":"source","value":"${respJson}"},{"name":"mode","value":"list"},{"name":"outputVariable","value":"rows"}],"fields":[{"name":"title","parserType":"JSONPATH","expression":"title"},{"name":"author","parserType":"JSONPATH","expression":"author"},{"name":"paragraphs","parserType":"JSONPATH","expression":"paragraphs"}]},{"id":"sql","shape":"sql","name":"查已存在古诗","x":700,"y":160,"params":[{"name":"datasource","value":"app"},{"name":"statement","value":"SELECT CONCAT(poem_title,''|'',poem_author) AS k FROM edu_poem"},{"name":"outputVariable","value":"existing"}],"fields":[]},{"id":"scr","shape":"script","name":"过滤已存在","x":920,"y":160,"params":[{"name":"script","value":"def seen=(existing?:[])*.k as Set; rows.unique{ it.title+''|''+it.author }.findAll{ !seen.contains(it.title+''|''+it.author) }"},{"name":"outputVariable","value":"fresh"}],"fields":[]},{"id":"out","shape":"output","name":"写入 edu_poem","x":1140,"y":160,"params":[{"name":"each","value":"${fresh}"},{"name":"key","value":"${title}|${author}"},{"name":"datasource","value":"app"},{"name":"targetTable","value":"edu_poem"},{"name":"cell:poem_title","value":"${title}"},{"name":"cell:poem_author","value":"${author}"},{"name":"cell:poem_content","value":"${join(paragraphs, ''\\\\\\\\\\\\\\\\n'')}"},{"name":"cell:poem_dynasty","value":"唐代"},{"name":"cell:poem_difficulty","value":"3"}],"fields":[]},{"id":"end","shape":"end","name":"结束","x":1360,"y":160,"params":[],"fields":[]}],"edges":[{"id":"e1","from":"start","to":"req"},{"id":"e2","from":"req","to":"ext"},{"id":"e3","from":"ext","to":"sql"},{"id":"e4","from":"sql","to":"scr"},{"id":"e5","from":"scr","to":"out"},{"id":"e6","from":"out","to":"end"}]}',
    collect_flow_remark = '采集全唐诗：开始节点列出 58 个分片（poet.tang.0..57000.json），抓取节点按 ${url} 循环逐片采集；源走 fastly.jsdelivr.net 镜像并开重试。',
